/* Round 7: recorded scalar closures and explicit quantum proof obligations. */
(() => {
  'use strict';
  const old=window.ResearchObservatory, D=window.OBSERVATORY_CLOSURES, H=window.ResearchHub;
  if(!old||!D||!H)return;
  const esc=H.escape, safe=H.safeURL;
  Object.assign(window.OBSERVATORY_RESEARCH.documents,D.documents);
  const pageNames={variables:'Variables & closures',finite:'Finite quantum modes',gravity:'Classical gravity',cutoff:'Cutoff & matching',proofs:'Bidirectional proof steps'};
  const current=()=>location.hash.split('/')[1]||'home';
  const url=k=>'#research/'+k;
  const link=(k,label)=>`<a class="hub-link" href="${url(k)}">${esc(label||pageNames[k])}</a>`;
  const eq=s=>`<div class="hub-eq" aria-label="Mathematical formulation">${esc(s)}</div>`;
  const table=(heads,rows)=>`<div class="hub-table-wrap"><table class="hub-table"><thead><tr>${heads.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const doc=(name,label)=>`<button data-r-doc="round7/${esc(name)}">${esc(label)}</button>`;
  const num=x=>Number.isFinite(x)?x.toExponential(3):'Unavailable';
  const f=D.finite.gates,g=D.gravity.cases.find(x=>x.parameters.name==='coupled_mixed')?.diagnostics;
  const nav=p=>`<nav class="hub-nav" aria-label="Variable closure research"><a href="#research">Research home</a>${Object.entries(pageNames).map(([k,v])=>`<a href="${url(k)}" ${k===p?'aria-current="page"':''}>${esc(v)}</a>`).join('')}</nav>`;
  const header=(title,text)=>`<header class="hub-header"><div><p class="hub-kicker">Physics Observatory · Review 7 · ${esc(D.date)}</p><h1>${esc(title)}</h1><p class="hub-deck">${esc(text)}</p></div></header>`;
  const panel=(title,body)=>`<section class="hub-panel"><h2>${esc(title)}</h2>${body}</section>`;
  const note=text=>`<div class="hub-note">${esc(text)}</div>`;
  const footer=()=>`<footer class="hub-foot">Recorded model calculations, conventional conditional proofs and open obligations have separate scopes. Agent review is not peer review or a formal proof kernel. <a href="/einstein-qed-variable-study.pdf" download>Download the detailed report (PDF)</a> · <a href="/research-review.zip" download>Download code, notes & raw data</a></footer>`;

  function plot(key){
    const p=D.plots[key];
    if(!p||!Array.isArray(p.series)||!p.series.length||!p.series.every(s=>s&&Array.isArray(s.points)&&s.points.length&&s.points.every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite))))return '<p role="status">No valid recorded data are available for this plot.</p>';
    return old.chart(p.series,{title:p.title,xLabel:p.xLabel,yLabel:p.yLabel,zero:true})+`<p class="hub-plot-caption">${esc(p.caption)}</p><a class="hub-link" href="${safe(p.csv)}" download>Download the plotted data (CSV)</a>`;
  }

  function homeSummary(){return `<section class="hub-panel closure-current"><p class="hub-kicker">Current extension · Review 7</p><h2>A new variable needs an equation and an energy budget.</h2><p>We introduced a dynamical scalar and verified its exchange with the electromagnetic field in two separate reduced models. A regulator-dependent subtraction also restores one coefficient gap algebraically. The common quantum current and directional stress needed to join these models remain open.</p><div class="hub-statgrid"><div class="hub-stat"><strong>2</strong><span>distinct reduced models simulated</span></div><div class="hub-stat"><strong>42</strong><span>independent skeptical checks</span></div><div class="hub-stat"><strong>47</strong><span>root validation checks</span></div><div class="hub-stat"><strong>17 + 11</strong><span>steps in the two main proof routes</span></div></div><div class="hub-grid"><article class="hub-card"><span class="hub-badge proof">Finite-model theorem</span><h3>${link('finite')}</h3><p>Action-derived scalar exchange preserves the work identity. The existing positive-gap estimate yields global continuation for each finite model.</p><p class="hub-meta">Main sampled energy residual: ${num(f.correct.max_energy_mismatch)}. No continuum or gravity claim.</p></article><article class="hub-card"><span class="hub-badge check">Classical benchmark</span><h3>${link('gravity')}</h3><p>Complete scalar and electromagnetic stress preserves the Einstein constraint. Removing one force produces the predicted drift.</p><p class="hub-meta">Mixed-case constraint residual: ${num(g?.max_constraint_abs_full)}. No quantum stress in this model.</p></article><article class="hub-card"><span class="hub-badge conditional">Coefficient lemma</span><h3>${link('cutoff')}</h3><p>Reference subtraction changes the fixed-coefficient premise. A bounded extra field cannot cancel the cofinal coefficient divergence under the stated assumptions.</p></article></div><div class="hub-actions"><a class="primary" href="#research/variables">Start with the variable guide</a>${link('proofs','Inspect all proof obligations')}<a href="/einstein-qed-variable-study.pdf" download>Read the detailed PDF</a></div><details><summary>How to interpret the new results</summary><p>The independent equations and root code checks support the specified mathematical models. They do not establish a new physical scalar, eliminate QED’s ultraviolet questions or solve the full Einstein–QED theory. The interrupted agent reviews and corrected implementation drafts are documented in the audit.</p></details></section><h2>Earlier foundation · Review 6</h2>`;}

  let variableQuery='',routeChoice='finite_continuation',plotChoice='finite';
  function variableRows(){
    const q=variableQuery.trim().toLowerCase();
    const rows=D.variables.filter(v=>!q||JSON.stringify(v).toLowerCase().includes(q));
    return `<p role="status" class="hub-meta">${rows.length} of ${D.variables.length} variable records</p>`+(rows.length?table(['Variable','What determines it','Conservation consequence','Missing obligation'],rows.map(v=>[v.symbol+' · '+v.type,v.determining_equation_or_input,v.ward_consequence,v.missing_proof])):'<p class="hub-empty">No variables match. Clear the search to see the full inventory.</p>');
  }
  function variables(){return header('Which freedom actually closes a gap?','Start with the kind of variable you want to change, then inspect its determining equation and the claim it can support.')+
    panel('How to use this extension',table(['Feature','Use it for','What remains conditional'],[
      ['Finite quantum modes','Read the action, energy proof and independent spinor comparison','Finite regulator and fixed magnetic background'],
      ['Classical gravity','Compare constraint-preserving and incomplete force equations','Classical scalar–EM stress on a regular interval'],
      ['Cutoff & matching','Distinguish a coefficient subtraction from physical renormalization','Common current/stress matching and limits'],
      ['Bidirectional steps','Trace each forward lemma and backward obligation','Only the supplied reviewed inference library'],
      ['Plots, CSV and PDF','Inspect recorded histories, parameters and full notes','Plot selection does not run a new cloud simulation']]))+
    panel('Four operations with different meanings',table(['Operation','Determining rule','Decision'],[
      ['Change chi with N,K','A fixed physical normalization and common action variations','Algebraic coefficient candidate; not complete renormalization'],
      ['Run e with mu_RG','Beta function, thresholds and reference charge','Scale evolution; not an arbitrary time function'],
      ['Prescribe chi(t)','External driver and its support work','Open energy sector until the support is included'],
      ['Add phi(x)','Scalar action, equation, initial data and stress','A new physical hypothesis that can be tested']])+note('Continuous interpolation of a Landau-index formula is a mathematical diagnostic. It does not create fractional Landau states. The interpolation symbol ν in the inventory is distinct from the scalar mass ratio ν in the finite model.'))+
    panel('Recorded experiments',`<label for="closure-plot">Select a completed calculation</label><select id="closure-plot">${Object.entries(D.plots).map(([k,v])=>`<option value="${esc(k)}" ${k===plotChoice?'selected':''}>${esc(v.title)}</option>`).join('')}</select><div id="closure-plot-view">${plot(plotChoice)}</div>`)+
    panel('Search every variable and its obligations',`<label for="closure-variable-search">Variable, state, scale or constraint</label><input id="closure-variable-search" type="search" value="${esc(variableQuery)}" placeholder="Scalar, matching, pressure…"><div id="closure-variable-results">${variableRows()}</div>`)+
    panel('Advisor decision and audit',`<p>The advisor selected the finite scalar bridge and a separate classical-gravity benchmark. The skeptic derived exchange identities independently. After the agents reached a usage limit, the root corrected the initial implementations and completed validation; no unfinished agent code review is presented as complete.</p><div class="hub-actions">${doc('advisor_plan.md','Read the plan and next experiments')}${doc('code_audit.md','Read concrete code defects and fixes')}${doc('renormalization_map.md','Read the detailed literature review')}</div>`)+
    panel('Primary references for this extension',D.sources.map(s=>`<article class="hub-source"><h3><a class="hub-link" href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></h3><p class="hub-meta">${esc(s.reading_scope||s.read_scope||s.inspected_sections||s.readdepth||s.use||s.supports||'Scope and limitations are recorded in the downloadable source ledger.')}</p></article>`).join(''));
  }

  function finite(){return header('A scalar closes a finite energy exchange.','The added field stores and returns energy. Its force and the corresponding Maxwell term are fixed by the same finite action.')+
    panel('Exact scope and units',`<p>Natural units use s = mt, a = eA_z/m, x = eE_z/m², b = |eB|/m² and φ = eΦ/m. The physical scalar is Φ; the energy unit is m⁴/e². Fixed positive mode masses, weights and canonical momenta define a finite hybrid model. No metric evolves here.</p>${eq('pᵢ = kᵢ − a;  hᵢ = (Mᵢ,0,pᵢ);  ωᵢ = √(Mᵢ²+pᵢ²)\nS = Σwᵢ(rᵢz+pᵢ/ωᵢ)\nC = ΣwᵢMᵢ²/(4ωᵢ⁵);  D = Σwᵢ5Mᵢ²pᵢ/(8ωᵢ⁷)\nU = Σwᵢ(hᵢ·rᵢ+ωᵢ)\nf(φ)=1+g²φ²;  fφ=2g²φ;  Z=f+χb−e²C')}`)+
    panel('Complete evolution equations',eq('a′ = −x;  rᵢ′ = 2hᵢ × rᵢ;  φ′ = y\ny′ = −ν²φ + ½fφ(x²−b²)\nZx′ = F(s) − e²(S+Dx²) − fφ yx')+`<p>The source is explicit. b is fixed, but f(φ)b²/2 remains part of the energy. Initial modes are the instantaneous negative-energy spinors, rᵢ = −hᵢ/ωᵢ. Scalar initial data and a smooth source complete the finite initial-value problem.</p><details><summary>Action and fixed source sign</summary>${eq('L = ½Za′² + ½φ′² − ½ν²φ² − ½fb² − aF\n  + e²Σwᵢ[ i(zᵢ†zᵢ′−zᵢ′†zᵢ)/2 − zᵢ†(hᵢ·σ)zᵢ − ωᵢ ]')}<p>Vary the potential, scalar and normalized spinors. The source term is −aF because a′=−x. C_a=2D fixes the coefficient derivative sign.</p></details>`)+
    panel('Five cancellations before any simulation',`<ol class="hub-steps"><li><strong>Keep mode coherence.</strong>Precession preserves Bloch norms and yields U′=xS.</li><li><strong>Differentiate the kinetic coefficient.</strong>Z′=fφ y+2e²Dx.</li><li><strong>Differentiate field and mode energy.</strong>The result is xF−fφ yx²/2.</li><li><strong>Differentiate scalar and magnetic energy.</strong>The result is +fφ yx²/2.</li><li><strong>Add the sectors.</strong>The complete shifted energy obeys W̃′=xF.</li></ol>${eq('W̃ = ½Zx² + e²U + ½y² + ½Ω²φ²;  Ω²=ν²+g²b²\n√W̃(s) ≤ √W̃(0) + (1/√(2μgap)) ∫₀ˢ |F(u)| du')}<p>For physical Bloch norms, U≥0. At b=10,K=20 the exact positive-quadrature family retains μgap=3/4 because f≥1. This bounds all finite state variables on finite intervals and gives global finite-model continuation. When Ω=0, the scalar is affine and the same continuation conclusion is handled separately.</p>${note('This is a conditional finite-dimensional theorem. It does not prove convergence as both regulators are removed, a bounded combined quantum current, or a gravitational stress closure.')}`)+
    panel('Recorded solution and its falsifier',plot('finite')+plot('work'))+
    panel('Verification ledger',table(['Check','Observed value','Interpretation'],[
      ['Main work residual',num(f.correct.max_energy_mismatch),'Sampled finite trajectory'],
      ['Wrong unaccounted energy',num(f.wrong.max_energy_mismatch),'Omitted Maxwell exchange is resolved'],
      ['Predicted wrong-work defect residual',num(f.wrong.max_defect_integral_residual),'Defect explains the broken identity'],
      ['nK=128 → 256 field/potential difference',num(f.node_refinement_max_abs_ax),'Fixed N,K; not regulator removal'],
      ['g=0 historical field difference',num(f.g0_baseline.max_abs_x),'Actual archived solver comparison'],
      ['Delayed response before probe',num(f.delayed_finite_difference.pre_probe_max_abs_derivative),'Centered response is causal to numerical tolerance']])+`<p>Independent complex spinors and RK45 challenge the production Bloch/DOP853 system. Zero drive, zero frequency, the zero-scalar invariant subspace and gauge translation are tested. The three response perturbation sizes agree, but this small-error regime does not demonstrate an asymptotic convergence order.</p><div class="hub-actions">${doc('variable_contract.md','Read every equation and proof assumption')}${link('proofs','Trace the 17-step proof')}${doc('code_audit.md','Inspect the implementation audit')}</div>`);
  }

  function gravity(){return header('Stress must support the evolving geometry.','This independent classical benchmark checks whether the scalar and electromagnetic field supply a mutually consistent source for Einstein’s equations.')+
    panel('Action, geometry and dimensionless fields',eq('S = ∫√−g [ MPl²(R−2Λ)/2 − (∇Φ)²/2 − V(Φ) − f(Φ)F²/4 ] d⁴x\nds² = −dt² + A(t)²(dx²+dy²) + Cmetric(t)²dz²\nτ=μt;  ϕ=Φ/MPl;  h=H/μ;  ℰ=E/(μMPl);  ℬ=B/(μMPl)\nf=exp(2cϕ);  U=½m̂²ϕ²;  λ=Λ/μ²\nℓA=log A;  ℓC=log Cmetric;  θ=2h⊥+h∥')+`<p>E and B are homogeneous orthonormal fields aligned along z. μ is a fixed reference frequency. There is no horizon or radial boundary in this homogeneous model; an initial Cauchy slice supplies the data.</p>${note('This action contains no Dirac field, quantum expectation value or pair-production current. Its scalar normalization and exponential f differ from the finite model’s polynomial f.')}`)+
    panel('Directional stress and complete ODEs',eq('ρEM=½f(ℰ²+ℬ²)\nρ=½v²+U+ρEM;  p⊥=½v²−U+ρEM;  p∥=½v²−U−ρEM\nℓA′=h⊥;  ℓC′=h∥;  ϕ′=v\nv′=−θv−m̂²ϕ−cf(ℬ²−ℰ²)\nℰ′=−(2h⊥+2cv)ℰ;  ℬ′=−2h⊥ℬ\nh⊥′=(λ−p∥−3h⊥²)/2\nh∥′=λ−p⊥−h⊥′−h⊥²−h∥²−h⊥h∥')+`<p>For A(0)=Cmetric(0)=1, the chosen initial isotropic rate h⊥=h∥=√((ρ₀+λ)/3) satisfies the constraint. Anisotropic stress can then separate the rates. A short contracting branch is tested separately. Negative initial radicands are rejected.</p>`)+
    panel('The geometric test cannot be imposed by hand',eq('Cg=h⊥²+2h⊥h∥−ρ−λ\nQ=ρ′+2h⊥(ρ+p⊥)+h∥(ρ+p∥)\nQEM=cfv(ℬ²−ℰ²);  Qscalar=−QEM\nCg′=−θCg−Qtotal;  Qtotal=0\nCg(τ)=Cg(0) exp(−∫θ dτ)')+`<p>The code evolves both spatial Einstein equations. It never resets h∥ to make Cg zero. The exact fluxes A²fℰ and A²ℬ provide a second formulation. This formulation shares the gravitational RHS; the skeptical script supplies a separately written equation check.</p>`)+
    panel('A deliberate missing force and the observed result',plot('gravity')+eq('Wrong control: omit only −cf(ℬ²−ℰ²) from v′\nQwrong=cfv(ℬ²−ℰ²)\nI′=exp(2ℓA+ℓC)Qwrong\nexp(2ℓA+ℓC)Cg+I=Cg(0)')+`<p>The weighted identity predicts the wrong-model constraint drift. It does not repair the model by redefining a pressure or imposing conservation afterward.</p>`)+
    panel('Eight bounded cases and exact fixtures',table(['Case','Correct |Cg| maximum','Wrong |Cg| maximum','DOP853 / Radau difference'],D.gravity.cases.map(c=>[c.parameters.name,num(c.diagnostics.max_constraint_abs_full),num(c.diagnostics.wrong_model_max_constraint_abs),num(c.diagnostics.max_full_vs_Radau_state_abs)]))+`<p>de Sitter analytic error: ${num(D.gravity.analytic_fixtures.de_sitter_max_abs_error)}. Massless-scalar analytic error: ${num(D.gravity.analytic_fixtures.massless_scalar_max_abs_error)}. Root holdouts also cover negative scalar coupling and equal initial E,B. These finite-time cases do not exclude later singularities.</p><div class="hub-actions">${doc('variable_contract.md','Read full geometry, fixtures and assumptions')}${link('proofs','Trace the 11-step constraint proof')}<a href="/gravity_case_summary.csv" download>Download case summaries</a></div>`);
  }

  function cutoff(){return header('A positive coefficient is one obligation.','Separate valid reference-subtraction algebra from a claim that physical Einstein–QED has been renormalized or completed.')+
    panel('A constructive reference-subtraction lemma',eq('χN,K = zref − 1 + e² CN,K(0)\nZN,K(a) = zref + e²[CN,K(0)−CN,K(a)] ≥ zref > 0')+`<p>This follows from the exact continuous-integral maximum at a=0. χ changes between regulator members but is constant in time within each fixed-background run. It changes the old fixed-χ premise, so the old obstruction does not refute this identity.</p>${note('The coefficient grows without bound along the joint regulator limit. Physical acceptance needs allowed action counterterms, a fixed charge normalization, a common state/current/stress prescription and convergence of observables. Positivity alone does not supply them.')}`)+
    panel('What a bounded new field cannot do',eq('|aN,K|≤A;  hN,K≤H;  N,K→∞ cofinally\nCN,K(aN,K) ≥ CN,K−A(0) → ∞\nZ=hN,K−e²CN,K(aN,K) → −∞')+`<p>A continuous f on a common compact scalar range is bounded. It cannot cancel this divergence under the theorem’s hypotheses. A scalar escaping with the regulator or a singular f changes the hypothesis and must be judged as a different physical model. This does not prove that all continuum QED constructions fail.</p>`)+
    panel('Three tempting shortcuts rejected by the skeptic',table(['Shortcut','Why the inference fails','Required next test'],[
      ['Call N or K the RG scale','No universal physical scale map has been derived','Match normalization, thresholds and operator content'],
      ['Apply the continuous maximum to every quadrature','Two-node Gauss quadrature gives a counterexample','Prove a maximum bound for the actual finite rule'],
      ['Make chi time-dependent without a support sector','The energy identity acquires a signed work defect','Specify an action and account for support energy']])+eq('Naive substitution into the old Maxwell equation: W′−xF=+½χ′x²\nTime-dependent kinetic action, including −χ′x in Maxwell: W′−xF=−½χ′x²'))+
    panel('The one-loop QED running equation is a separate statement',eq('μRG de/dμRG = e³/(12π²) + O(e⁵)\n1/e²(μRG) = 1/e²(μ₀) − log(μRG/μ₀)/(6π²) [displayed order]')+`<p>The formal pole comes from extrapolating this approximation. It is not an observed instability or a proof that the finite separated coefficient has the same physical meaning. Coupling-running arguments must keep a fixed physical normalization.</p>`)+
    panel('The actual object still to control',eq('Jcombined = S − Cx′ + Dx²')+`<p>C is only one part of the current. Its subtraction must be compatible with the state-dependent terms, energy and both directional pressures. In evolving geometry, the physical momenta, magnetic field and mode basis change together. Adding φ does not compute those missing variations.</p><div class="hub-actions">${doc('renormalization_map.md','Read the complete renormalization analysis')}${doc('skeptic_review.md','Read the counterexamples and exact identities')}${link('proofs','Inspect matching and obstruction routes')}</div>`);
  }

  const routeLabels={finite_continuation:'Finite continuation · 17 rules',gravity_constraint:'Gravity constraint · 11 rules',reference_coefficient:'Reference coefficient · 4 rules',bounded_addition_obstruction:'Bounded addition obstruction · 4 rules',missing_Maxwell_certificate:'Withdrawn Maxwell certificate · underivable',common_quantum_closure:'Common Einstein–QED closure · open'};
  function routeContent(){
    const item=D.routes[routeChoice];
    if(!item)return '<p role="status">This proof route is unavailable.</p>';
    const L=item.library,R=item.result;
    const find=id=>L.nodes.find(n=>n.id===id);
    const steps=R.certified_proof?.steps||[];
    return `<div class="hub-badges"><span class="hub-badge ${steps.length?'proof':'open'}">${steps.length?'Checked route under declared model premises':'Not derivable in this finite library'}</span></div><h3>Declared domain</h3><p>${esc(find(L.initial_facts[0])?.statement||'Missing domain')}</p><h3>Target</h3><p>${esc(find(L.goals[0])?.statement||'Missing target')}</p>${steps.length?`<ol class="hub-steps">${steps.map(s=>`<li><strong>${esc(s.rule_id)} · ${esc(s.conclusion)}</strong>${esc(find(s.conclusion)?.statement)}<details><summary>Previous premises and certificate</summary><p>${s.premises.map(p=>esc(p)+': '+esc(find(p)?.statement)).join('<br>')}</p><p class="hub-meta">${esc(L.rules.find(r=>r.id===s.rule_id)?.proof_ref)}</p></details></li>`).join('')}</ol>`:`<p>No complete route was admitted. Missing premises must be calculated, not promoted to assumptions after a failed search.</p>${L.proposed_obligations?table(['Open calculation','Status'],L.proposed_obligations.map(id=>[find(id)?.statement||id,'No reviewed sufficient derivation supplied'])):'<p>The Maxwell-equation certificate was intentionally withdrawn. The separate physical wrong-model run tests the resulting exchange defect; the graph withdrawal itself tests inference discipline.</p>'}`}<details><summary>All nodes, including unproved obligations</summary>${table(['ID','Type','Statement'],L.nodes.map(n=>[n.id,n.kind,n.statement]))}</details><p class="hub-meta">Cost: ${esc(R.certified_cost??'No certified route')}. Heuristic h=0. ${esc(R.optimality_certificate||R.reason||'')}</p>`;
  }
  function proofs(){return header('Meet the obligations from both directions.','Forward reasoning supplies supported lemmas. Backward reasoning asks what would be sufficient for the target. The two sides meet only when every required premise is available.')+
    panel('What the algorithm can certify',eq('Forward: declared action and domain → differentiated identities → bounds\nBackward: target → all sufficient obligations → required certificates\nMeeting: every required obligation is in the forward facts\nVerification: replay the rules and independently check route cost')+`<p>This reuses the audited finite ground-Horn planner. Its bidirectional search has h=0; a separate forward uniform-cost search certifies the route cost. That cost counts reviewed rule applications. It does not measure scientific plausibility. The code checks metadata and inference replay; conventional proof notes are not checked by a mathematical proof kernel.</p>${note('“Not derivable” means missing in this finite reviewed library. It is not a theorem that no solution exists. Proposed quantum bridge obligations are not secretly admitted as executable rules.')}`)+
    panel('Explore each substep',`<label for="closure-route">Select a target and its reviewed premises</label><select id="closure-route">${Object.entries(routeLabels).map(([k,v])=>`<option value="${esc(k)}" ${k===routeChoice?'selected':''}>${esc(v)}</option>`).join('')}</select><div id="closure-route-view">${routeContent()}</div>`)+
    panel('The next useful experiment',`<p>Derive a causal quantum current and both directional stresses in a prescribed smooth axial geometry and one stated quantum state. Fix allowed subtractions and a physical normalization together. Evaluate the force Ward identity from those independently computed observables. Only after it passes should the metric evolve self-consistently.</p><p>Do not reconstruct a pressure by solving the Ward identity that is supposed to test the calculation. Do not identify the finite polynomial f and classical exponential f through a unit conversion.</p><div class="hub-actions">${doc('advisor_plan.md','Read the prioritized experiment designs')}${doc('search_contract.md','Read search semantics and integrity checks')}<a href="/closure-proof-map.json" download>Download graph and complete search traces</a></div>`);
  }

  function render(page='home'){
    if(!Object.hasOwn(pageNames,page))return old.render(page);
    const fun={variables,finite,gravity,cutoff,proofs}[page];
    return `<div class="research-shell hub closures">${nav(page)}${fun()}${footer()}</div>`;
  }
  function afterRender(){if(Object.hasOwn(pageNames,current()))document.title=pageNames[current()]+' · Physics Observatory';else old.afterRender();}
  document.addEventListener('input',event=>{if(event.target.id==='closure-variable-search'){variableQuery=event.target.value;const el=document.querySelector('#closure-variable-results');if(el)el.innerHTML=variableRows();}});
  document.addEventListener('change',event=>{
    if(event.target.id==='closure-plot'&&Object.hasOwn(D.plots,event.target.value)){plotChoice=event.target.value;const el=document.querySelector('#closure-plot-view');if(el)el.innerHTML=plot(plotChoice);}
    if(event.target.id==='closure-route'&&Object.hasOwn(D.routes,event.target.value)){routeChoice=event.target.value;const el=document.querySelector('#closure-route-view');if(el)el.innerHTML=routeContent();}
  });
  window.ResearchClosures={render,homeSummary,plot,routeContent};
  window.ResearchObservatory={...old,render,afterRender};
})();
